 private static function row():array{return json_decode(file_get_contents('D:/opencode/conversao-sc/.runtime/ciw-completion-20261028/container-attachments-download/local/attachment-reference-actual.json'),true,512,JSON_THROW_ON_ERROR)['data'];}
