 private static function entity(array $endpoint):BuilderEntity{
  $api=['responseContract'=>'sursum-programs','authHeaders'=>[],'detailEndpoint'=>$endpoint,'detailResponse'=>['itemPath'=>'data'],'listEndpoint'=>['url'=>$endpoint['url'],'method'=>'POST','bodyTemplate'=>['resource'=>'anexos','operation'=>'read'],'requestContextFields'=>['container_id']],'listResponse'=>['itemsPath'=>'data']];
  $e=(new BuilderEntity())->setCode('container_anexos_progress')->setEntityType('api')->setMetadata(['apiSource'=>$api,'apiBinding'=>['sourceCode'=>'motor_progress_container_painel']]);
  foreach(self::row()as$name=>$value){if($name==='cod_estabel')continue;$type=in_array($name,['anexo_container_id','container_id','item_container_id','tipos_anexo_id'],true)?'integer':($name==='tem_arquivo'?'boolean':($name==='dt_hr_arquivo'?'datetime':'string'));$e->addField((new BuilderField())->setCode($name)->setLabel($name)->setDataType($type)->setRequired(false)->setPrimaryKey($name==='anexo_container_id')->setOptions(['readonly'=>true,'writable'=>false]));}return $e;
 }
 private function service(array $body,array &$sent,array &$logs,?RuntimeFileTransferContext $files=null,?AttachmentStorageClient $storage=null,?array $endpoint=null,bool $actor=true,bool $allowed=true):RuntimeApiEntityActionService{
  $repo=$this->createStub(BuilderEntityRepository::class);$repo->method('findOneBy')->willReturn(self::entity($endpoint??self::endpoint()));
  $em=$this->createStub(EntityManagerInterface::class);$em->method('persist')->willReturnCallback(static function($item)use(&$logs){if($item instanceof RuntimeTransactionLog)$logs[]=$item;});
  $permissions=$this->createStub(PermissionResolver::class);$permissions->method('hasPermission')->willReturn($allowed);$permissions->method('getTenantId')->willReturn('default');
  $tx=new RuntimeTransactionService($em,$permissions,new RuntimeExecutionContext(),$this->createStub(RuntimeEntityDefinitionResolver::class),$this->createStub(RuntimeEnvironmentIdentityResolver::class));(new \ReflectionProperty($tx,'current'))->setValue($tx,(new RuntimeTransaction())->setTenantId('default')->setRequestContext($actor?['actor'=>['source'=>'authenticated-session','version'=>1,'username'=>'real-user']]:[]));
  $client=$this->createStub(RuntimeExternalJsonClient::class);$client->method('request')->willReturnCallback(static function($url,$method,$headers,$request)use($body,&$sent){$sent[]=$request;return ['status'=>200,'body'=>$body];});
  return new RuntimeApiEntityActionService($repo,$tx,$client,$permissions,files:$files,attachmentStorage:$storage);
 }
 private static function payload():array{return ['id'=>5,'context'=>['container_id'=>71]];}
 private function call(RuntimeApiEntityActionService $s,string $operation,array $p):array{return $s->handle('ciw.container-anexos',$operation==='download'?'attachments.download':$operation,['entityCode'=>'container_anexos_progress','operation'=>$operation],$p);}
 public function testActualRawTTGetUsesClosedContextAndIgnoresBrowserReference():void{
  $sent=[];$logs=[];$p=self::payload();$p['anexo_container_id']=5;$p['record']=self::row();$p['record']['caminho_arquivo']='forged.pdf';$row=$this->call($this->service(['success'=>true,'data'=>self::row()],$sent,$logs),'get',$p);
  self::assertSame('historico.exe',$row['caminho_arquivo']);self::assertNull($row['item_container_id']);self::assertSame('  Memoria Sao Jose  ',$row['descricao']);self::assertCount(9,$row);self::assertArrayNotHasKey('cod_estabel',$row);self::assertSame(['resource'=>'anexos-arquivo','operation'=>'get','id'=>5,'anexo_container_id'=>5,'container_id'=>71],$sent[0]);self::assertCount(1,$logs);
 }
 public function testExistingListAndLegacyGetRemainReadonlyAndContextual():void{
  $row=self::row();unset($row['cod_estabel'],$row['caminho_arquivo']);$sent=[];$logs=[];$read=$this->call($this->service(['success'=>true,'data'=>[$row]],$sent,$logs),'read',['context'=>['container_id'=>71]]);self::assertSame(1,$read['total']);self::assertNull($read['data'][0]['caminho_arquivo']);self::assertSame('anexos',$sent[0]['resource']);
  $old=self::endpoint();$old['bodyTemplate']['resource']='anexos';$sent=[];$logs=[];$get=$this->call($this->service(['success'=>true,'data'=>$row],$sent,$logs,endpoint:$old),'get',self::payload());self::assertSame(5,$get['anexo_container_id']);self::assertNull($get['caminho_arquivo']);
  $row['container_id']=72;$sent=[];$logs=[];try{$this->call($this->service(['success'=>true,'data'=>[$row]],$sent,$logs),'read',['context'=>['container_id'=>71]]);self::fail('Cross-container listing accepted');}catch(RuntimeHttpException $e){self::assertSame(502,$e->getStatusCode());}self::assertSame([],$logs);
 }
 public function testIdorAndRawShapeAreRejectedBeforeStorageAndSuccessLog():void{
  $base=self::row();$cases=[];foreach(['container_id'=>72,'anexo_container_id'=>6,'cod_estabel'=>'101','tem_arquivo'=>false,'item_container_id'=>'0']as$k=>$v){$r=$base;$r[$k]=$v;$cases[]=['success'=>true,'data'=>$r];}$r=$base;unset($r['caminho_arquivo']);$cases[]=['success'=>true,'data'=>$r];$cases[]=['success'=>true,'data'=>$base+['extra'=>'path']];$cases[]=['success'=>true,'data'=>$base,'committed'=>true];$cases[]=['success'=>true,'data'=>$base,'audit'=>[]];
  $cases[]=['success'=>true,'data'=>null];$cases[]=['success'=>false,'data'=>$base];
  foreach($cases as$body){$sent=[];$logs=[];$files=new RuntimeFileTransferContext();$files->begin([]);$storage=$this->createMock(AttachmentStorageClient::class);$storage->expects(self::never())->method('get');try{$this->call($this->service($body,$sent,$logs,$files,$storage),'download',self::payload());self::fail('Bad raw row accepted');}catch(RuntimeHttpException $e){self::assertSame(502,$e->getStatusCode());}self::assertCount(1,$sent);self::assertSame([],$logs);$files->clear();}
 }
 public function testBadRequestsAndBindingsNeverReachProgressOrStorage():void{
  $base=self::payload();$cases=[['id'=>5],['id'=>5,'context'=>['container_id'=>71,'other'=>1]],$base+['caminho_arquivo'=>'forged.pdf'],$base+['actor'=>'forged'],$base+['anexo_container_id'=>6],['id'=>'5','context'=>['container_id'=>71]],['id'=>5,'context'=>['container_id'=>'71']],$base+['record'=>['anexo_container_id'=>6]],$base+['record'=>['container_id'=>72]]];
  foreach($cases as$p){$sent=[];$logs=[];$files=new RuntimeFileTransferContext();$files->begin([]);$storage=$this->createMock(AttachmentStorageClient::class);$storage->expects(self::never())->method('get');try{$this->call($this->service(['success'=>true,'data'=>self::row()],$sent,$logs,$files,$storage),'download',$p);self::fail('Invalid request accepted');}catch(RuntimeHttpException $e){self::assertSame(422,$e->getStatusCode());}self::assertSame([],$sent);$files->clear();}
  foreach(['method'=>'GET','requestContextFields'=>[],'url'=>'https://example.invalid/med/web/SursumPrograms/containers-painel','bodyTemplate'=>['resource'=>'anexos','operation'=>'get']]as$k=>$v){$ep=self::endpoint();$ep[$k]=$v;$sent=[];$logs=[];$files=new RuntimeFileTransferContext();$files->begin([]);$storage=$this->createMock(AttachmentStorageClient::class);$storage->expects(self::never())->method('get');try{$this->call($this->service(['success'=>true,'data'=>self::row()],$sent,$logs,$files,$storage,$ep),'download',self::payload());self::fail('Invalid binding accepted');}catch(RuntimeHttpException $e){self::assertSame(422,$e->getStatusCode());}self::assertSame([],$sent);$files->clear();}
 }
 public function testAuthenticatedDownloadUsesRealBrokerPolicyAndDiscardsOnlyTemporaryBytes():void{
  $dir=sys_get_temp_dir().'/ciw-container-attachment-'.bin2hex(random_bytes(6));mkdir($dir);mkdir($dir.'/root');mkdir($dir.'/private');$secret=random_bytes(32);$bytes="historical bytes\x00\xff";file_put_contents($dir.'/root/historico.exe',$bytes);
  try{$broker=new AttachmentStorageBroker($dir.'/root',$dir.'/private',$secret);$storage=new class($broker,$secret)extends AttachmentStorageClient{
   public array $calls=[];public function __construct(private AttachmentStorageBroker $broker,private string $secret){}public function get(string $reference,string $owner):array{$this->calls[]=[$reference,$owner];$e=['v'=>1,'op'=>'get','requestId'=>bin2hex(random_bytes(16)),'timestamp'=>time(),'nonce'=>bin2hex(random_bytes(16)),'owner'=>$owner,'reference'=>$reference];$encoded=base64_encode(json_encode($e,JSON_THROW_ON_ERROR));$r=$this->broker->execute($encoded,hash_hmac('sha256',$encoded,$this->secret),null);$temp=tempnam(sys_get_temp_dir(),'ciw-container-bytes-');copy($r['path'],$temp);return ['path'=>$temp,'size'=>$r['size'],'sha256'=>$r['sha256'],'fileName'=>$r['fileName']];}
  };$files=new RuntimeFileTransferContext();$files->begin([]);$sent=[];$logs=[];$p=self::payload();$p['_runtime']=['actor'=>['username'=>'forged']];$p['record']=['caminho_arquivo'=>'forged.pdf'];$result=$this->call($this->service(['success'=>true,'data'=>self::row()],$sent,$logs,$files,$storage),'download',$p);
   self::assertSame(['download'=>true],$result);self::assertSame('historico.exe',$storage->calls[0][0]);self::assertSame(hash('sha256',json_encode(['real-user','container_anexos_progress',71,null,5],JSON_THROW_ON_ERROR)),$storage->calls[0][1]);$response=$files->takeDownload();self::assertInstanceOf(BinaryFileResponse::class,$response);self::assertSame('no-store, private',$response->headers->get('Cache-Control'));self::assertSame('nosniff',$response->headers->get('X-Content-Type-Options'));self::assertStringContainsString('historico.exe',$response->headers->get('Content-Disposition'));$temp=$response->getFile()->getPathname();self::assertSame($bytes,file_get_contents($temp));$response->prepare(Request::create('/'));ob_start();$response->sendContent();$actual=ob_get_clean();self::assertSame($bytes,$actual);self::assertFileDoesNotExist($temp);self::assertFileExists($dir.'/root/historico.exe');$files->clear();
  }finally{$this->removeTree($dir);}
 }
 public function testMissingFileIdentityPermissionAndAllWritesFailClosed():void{
  foreach([null,'','   ']as$reference){$row=self::row();$row['caminho_arquivo']=$reference;$row['tem_arquivo']=false;$sent=[];$logs=[];$files=new RuntimeFileTransferContext();$files->begin([]);$storage=$this->createMock(AttachmentStorageClient::class);$storage->expects(self::never())->method('get');try{$this->call($this->service(['success'=>true,'data'=>$row],$sent,$logs,$files,$storage),'download',self::payload());self::fail('Missing reference accepted');}catch(RuntimeHttpException $e){self::assertSame(404,$e->getStatusCode());}$files->clear();}
  foreach([[false,true,401],[true,false,403]]as[$actor,$allowed,$status]){$sent=[];$logs=[];$files=new RuntimeFileTransferContext();$files->begin([]);$storage=$this->createMock(AttachmentStorageClient::class);$storage->expects(self::never())->method('get');try{$this->call($this->service(['success'=>true,'data'=>self::row()],$sent,$logs,$files,$storage,actor:$actor,allowed:$allowed),'download',self::payload());self::fail('Missing access accepted');}catch(RuntimeHttpException $e){self::assertSame($status,$e->getStatusCode());}self::assertSame([],$sent);$files->clear();}
  foreach(['create','update','delete','batch','process']as$op){$sent=[];$logs=[];try{$this->call($this->service(['success'=>true,'data'=>self::row()],$sent,$logs),$op,self::payload());self::fail('Writer accepted');}catch(RuntimeHttpException $e){self::assertSame(405,$e->getStatusCode());}self::assertSame([],$sent);}
 }
 private function removeTree(string $path):void{$root=realpath($path);if(!$root||is_link($path)||dirname($root)!==realpath(sys_get_temp_dir())||!preg_match('/^ciw-container-(?:attachment|history)-[a-f0-9]+$/D',basename($root))){throw new \RuntimeException('Fixture cleanup outside owned temp root');}foreach(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST)as$p){if(!str_starts_with($p->getPathname(),$root.DIRECTORY_SEPARATOR)){throw new \RuntimeException('Fixture cleanup boundary invalid');}$p->isDir()&&!$p->isLink()?rmdir($p->getPathname()):unlink($p->getPathname());}rmdir($root);}
 public function testRealBrokerRetainsHistoricalSizeAndRejectsPaths():void{
  $dir=sys_get_temp_dir().'/ciw-container-history-'.bin2hex(random_bytes(6));mkdir($dir);mkdir($dir.'/root');mkdir($dir.'/private');$secret=random_bytes(32);$f=fopen($dir.'/root/.historico.exe','w+b');ftruncate($f,20971521);fclose($f);
  try{$broker=new AttachmentStorageBroker($dir.'/root',$dir.'/private',$secret);$get=static function(string $name)use($broker,$secret){$e=['v'=>1,'op'=>'get','requestId'=>bin2hex(random_bytes(16)),'timestamp'=>time(),'nonce'=>bin2hex(random_bytes(16)),'owner'=>str_repeat('a',64),'reference'=>$name];$encoded=base64_encode(json_encode($e,JSON_THROW_ON_ERROR));return $broker->execute($encoded,hash_hmac('sha256',$encoded,$secret),null);};$r=$get('.historico.exe');self::assertSame(20971521,$r['size']);self::assertSame(hash_file('sha256',$dir.'/root/.historico.exe'),$r['sha256']);
   foreach(['../.historico.exe','folder/file.pdf','folder\\file.pdf','https://example.invalid/a.pdf',"name\x00.pdf",'.','..']as$name){try{$get($name);self::fail('Arbitrary path accepted');}catch(\RuntimeException $e){self::assertStringContainsString('reference',$e->getMessage());}}
   self::assertSame(20971521,filesize($dir.'/root/.historico.exe'));
  }finally{$this->removeTree($dir);}
 }
 public function testUploadedBytesAreRejectedBeforeProgressOrStorage():void{
  $path=tempnam(sys_get_temp_dir(),'ciw-container-upload-');file_put_contents($path,'%PDF-1.4');try{$files=new RuntimeFileTransferContext();$files->begin(['arquivo_upload'=>new \Symfony\Component\HttpFoundation\File\UploadedFile($path,'fixture.pdf',null,UPLOAD_ERR_OK,true)]);$sent=[];$logs=[];$storage=$this->createMock(AttachmentStorageClient::class);$storage->expects(self::never())->method('get');try{$this->call($this->service(['success'=>true,'data'=>self::row()],$sent,$logs,$files,$storage),'download',self::payload());self::fail('Upload accepted by download');}catch(RuntimeHttpException $e){self::assertSame(405,$e->getStatusCode());}self::assertSame([],$sent);self::assertSame([],$logs);$files->clear();}finally{unlink($path);}
 }
